--
-- Table structure for table `fact_orders`
--

DROP TABLE IF EXISTS `fact_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `fact_orders` (
  `Order_ID` varchar(30) NOT NULL,
  `Date_ID` varchar(30) NOT NULL,
  `Customer_ID` varchar(30) NOT NULL,
  `Product_ID` varchar(30) NOT NULL,
  `Location_ID` varchar(30) NOT NULL,
  `Quantity` int DEFAULT NULL,
  `Unit_Price` double DEFAULT NULL,
  `Discount_Pct` int DEFAULT NULL,
  `Sales` double DEFAULT NULL,
  `Cost` double DEFAULT NULL,
  `Profit` double DEFAULT NULL,
  `Payment_Method` text,
  `Order_Status` text,
  `Delivery_Days` int DEFAULT NULL,
  KEY `fk_orders_customer` (`Customer_ID`),
  KEY `fk_orders_product` (`Product_ID`),
  KEY `fk_orders_date` (`Date_ID`),
  KEY `fk_orders_location` (`Location_ID`),
  CONSTRAINT `fk_orders_customer` FOREIGN KEY (`Customer_ID`) REFERENCES `dim_customer` (`Customer_ID`),
  CONSTRAINT `fk_orders_date` FOREIGN KEY (`Date_ID`) REFERENCES `dim_date` (`Date_ID`),
  CONSTRAINT `fk_orders_location` FOREIGN KEY (`Location_ID`) REFERENCES `dim_location` (`Location_ID`),
  CONSTRAINT `fk_orders_product` FOREIGN KEY (`Product_ID`) REFERENCES `dim_product` (`Product_ID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `fact_orders`
--

